import type { Api, Model } from "@earendil-works/pi-ai";

const PROXY_PATH = "/api/chat-proxy";

const DIRECT_HOST_SUFFIXES = [
	"api.openai.com",
	"generativelanguage.googleapis.com",
	"api.groq.com",
	"api.x.ai",
	"api.mistral.ai",
	"huggingface.co",
	"api.cerebras.ai",
	"amazonaws.com",
	"azure.com",
	"github.com",
	"openrouter.ai",
];

function currentOrigin(): string {
	return globalThis.location?.origin ?? "";
}

function hostnameMatches(hostname: string, suffix: string): boolean {
	return hostname === suffix || hostname.endsWith(`.${suffix}`);
}

function isLocalHost(hostname: string): boolean {
	return hostname === "localhost" || hostname === "127.0.0.1" || hostname === "::1";
}

function parseUrl(value: string): URL | null {
	try {
		return new URL(value, currentOrigin() || "http://localhost");
	} catch {
		return null;
	}
}

export function chatProxyBaseUrl(): string {
	const origin = currentOrigin();
	return origin ? `${origin}${PROXY_PATH}` : PROXY_PATH;
}

export function proxyTargetHeader(baseUrl: string): string {
	return baseUrl.replace(/\/+$/, "");
}

export function shouldProxyModel(model: Model<Api>): boolean {
	if (!model.baseUrl || model.provider === "browser") return false;
	if (model.provider === "notorganic") return false;
	if (model.provider === "anthropic" || model.api === "anthropic-messages") return true;

	const url = parseUrl(model.baseUrl);
	if (!url) return true;

	if (url.origin === currentOrigin() && url.pathname.startsWith(PROXY_PATH)) return false;
	if (isLocalHost(url.hostname)) return true;

	return !DIRECT_HOST_SUFFIXES.some((suffix) => hostnameMatches(url.hostname, suffix));
}

export function proxiedProviderRequestUrl(targetUrl: string): { url: string; targetBaseUrl: string } {
	const parsed = new URL(targetUrl);
	return {
		url: `${chatProxyBaseUrl()}${parsed.pathname}${parsed.search}`,
		targetBaseUrl: parsed.origin,
	};
}
import { defineEventHandler, proxyRequest, getHeader, getRequestURL, getHeaders, createError } from "h3";
import { buildValidatedProxyUrl } from "../../utils/proxy-target";

export default defineEventHandler(async (event) => {
  const targetBaseUrl = getHeader(event, "x-target-url");

  if (!targetBaseUrl) {
    throw createError({
      statusCode: 400,
      statusMessage: "Missing x-target-url header",
    });
  }

  const reqUrl = getRequestURL(event);
  const proxyPath = reqUrl.pathname.replace(/^\/api\/chat-proxy\/?/, "") + reqUrl.search;
  let fullTargetUrl: string;
  try {
    fullTargetUrl = buildValidatedProxyUrl(targetBaseUrl, proxyPath, {
      allowHttp: process.dev || import.meta.env?.DEV,
      allowLocal: process.dev || import.meta.env?.DEV,
    });
  } catch (err) {
    throw createError({
      statusCode: 400,
      statusMessage: err instanceof Error ? err.message : "Invalid proxy target",
    });
  }

  const forbiddenHeaders = [
    "x-stainless-os",
    "x-stainless-lang",
    "x-stainless-package-version",
    "x-stainless-runtime",
    "x-stainless-runtime-version",
    "x-stainless-arch",
    "x-stainless-os-version",
    "origin",
    "host",
    "referer",
    "x-target-url",
  ];

  const headers: Record<string, string> = { ...getHeaders(event) };
  for (const forbidden of forbiddenHeaders) {
    delete headers[forbidden];
  }

  if (process.dev || import.meta.env?.DEV) {
    const hasAuth = !!headers["authorization"];
    const hasApiKey = !!headers["x-api-key"];
    console.log(`[chat-proxy] ${event.method} ${proxyPath} -> ${new URL(fullTargetUrl).hostname} (auth=${hasAuth}, xApiKey=${hasApiKey})`);
  }

  return proxyRequest(event, fullTargetUrl, {
    headers,
  });
});

