	const sanitized = {
		...request,
		...(request.name ? { name: String(analyticsUrl(request.name)) } : {}),
	} as T & Record<string, unknown>;
	delete sanitized.requestHeaders;
	delete sanitized.responseHeaders;
	delete sanitized.requestBody;
	delete sanitized.responseBody;
	return sanitized;
}

